#include <bits/stdc++.h>
using namespace std;

vector<long long> find_divisors(long long n) {
    vector<long long> result;
    for (long long candidate = 1; candidate * candidate <= n; ++candidate) {
        if (n % candidate == 0) {
            result.push_back(candidate);
            if (candidate != n / candidate) {
                result.push_back(n / candidate);
            }
        }
    }
    sort(result.begin(), result.end());
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    const long long MOD_CONST = 1000000007;
    long long p_input, k_input;
    cin >> p_input >> k_input;

    if (k_input == 0) {
        long long result = 1;
        long long base = p_input % MOD_CONST;
        long long exp = p_input - 1;
        long long base_mod = base;
        while (exp > 0) {
            if (exp & 1) result = (result * base_mod) % MOD_CONST;
            base_mod = (base_mod * base_mod) % MOD_CONST;
            exp >>= 1;
        }
        cout << result << "\n";
    } else if (k_input == 1) {
        long long result = 1;
        long long base = p_input % MOD_CONST;
        long long exp = p_input;
        long long base_mod = base;
        while (exp > 0) {
            if (exp & 1) result = (result * base_mod) % MOD_CONST;
            base_mod = (base_mod * base_mod) % MOD_CONST;
            exp >>= 1;
        }
        cout << result << "\n";
    } else {
        vector<long long> divisors = find_divisors(p_input - 1);
        for (auto div : divisors) {
            if ((p_input - 1) % div == 0) {
                long long power_result = 1;
                long long base = k_input % p_input;
                long long exp = div;
                long long base_mod = base;
                while (exp > 0) {
                    if (exp & 1) power_result = (power_result * base_mod) % p_input;
                    base_mod = (base_mod * base_mod) % p_input;
                    exp >>= 1;
                }
                if (power_result == 1) {
                    long long result = 1;
                    long long base2 = p_input % MOD_CONST;
                    long long exp2 = (p_input - 1) / div;
                    long long base2_mod = base2;
                    while (exp2 > 0) {
                        if (exp2 & 1) result = (result * base2_mod) % MOD_CONST;
                        base2_mod = (base2_mod * base2_mod) % MOD_CONST;
                        exp2 >>= 1;
                    }
                    cout << result << "\n";
                    break;
                }
            }
        }
    }
    return 0;
}
